/* @socom-skeleton body __ct__6CValveFPCcUi10VALVE_TYPE */
CValve::CValve(const char* name, u32 value, VALVE_TYPE type)
{
	m_list.clear();
	
	m_name = NULL;
	m_name_pooled = false;
	m_pooled = false;
	m_value = value;
	m_type = (u32)VALVE_TYPE::VTYPE_NONE;

	FreeName();

	if (name)
	{
		m_name = zstrdup(name);
	}
}

