/* @socom-skeleton body FreeName__6CValveFv */
void CValve::FreeName()
{
	if (m_name_pooled)
	{
		if (m_name)
		{
			zfree(m_name);
		}

		m_name = NULL;
	}
	else
	{
		m_name = NULL;
	}

	m_name_pooled = false;
}

